//! Original native outputs, consumed by the actual production ECS system.
//! Generator capture_rotate_ops.py executes the complete3596-byte original body.
use super::ui_rotate_lantern::*;
use super::ui_decorator_affordance_dispatch::DecoratorAffordanceDispatcher;
use bevy_ecs::prelude::*;
use country_core::{resources::{read_mouse_depth_value::MouseDepthValue,
    terrain_height::{TerrainHeightSsbo,TerrainHeightsData},mouse_terrain_raycast::CameraCursorRay,
    walls::{cached_decorator_transforms::CachedDecoratorTransforms,decorator::*,decorator_storage::*,decorator_archivist::DecoratorArchivist},
    time::GameTime,window::WindowSize},systems::{audio::PlayDecoratorSoundCmd,camera_rig::MainCamera,
    ui::{resources::ui_state::{UiState,UiInteraction,WidgetId},signifiers::signifier_create::UiSignifierStream},
    ui_clutter::ui_focus_decoclutter::RequestRotateDecorator,collision::world::RaycastWorldResult}};
use crate::{backup::DecoratorBackup,deferred_decorator_history::DeferredDecoratorEditHistory};
use glam::{Vec3,Mat4};
struct Native {dst:u8,raw:u8,ty:u8,small:bool,op:&'static str,audio:&'static str,local:&'static str,event:&'static str}
fn bytes(s:&str)->Vec<u8>{s.as_bytes().chunks_exact(2).map(|c|u8::from_str_radix(std::str::from_utf8(c).unwrap(),16).unwrap()).collect()}
fn word(s:&[u8],at:usize)->u32{u32::from_le_bytes(s[at..at+4].try_into().unwrap())}
fn scalar(s:&[u8],at:usize)->f32{f32::from_bits(word(s,at))}
fn close(a:f32,b:f32){assert!((a-b).abs()<0.00001 || a.to_bits()==b.to_bits(),"{a:?} != native {b:?}")}

#[test]
fn actual_rotation_ecs_matches_all_native_phases_and_preserves_existing_info() {
 for case in NATIVE {
    let id=DecoratorId(71);
    let addr=if case.dst==4 {DecoratorStorageAddr::Stair} else {DecoratorStorageAddr::Terrain};
    let mut input=[0x91u8;72];
    for (offset,value) in [(0,2f32),(4,4.),(8,0.25),(12,7.),(16,0.25)] {input[offset..offset+4].copy_from_slice(&value.to_le_bytes());}
    input[0x22]=case.dst;input[0x44]=2;input[0x46]=case.ty;
    let before=crate::apply_decorator_op::bytes_to_info(&input);
    let mut world=World::new();
    let mut storage=DecoratorStorage::default();
    storage.get_or_insert_default(addr).insert(id,before);
    storage.decorator_to_storage.insert(id,addr);
    world.insert_resource(storage);
    let mut transforms=CachedDecoratorTransforms::default();
    transforms.insert(id.0,country_core::resources::walls::cached_decorator_transforms::CachedDecoratorTransform::from_components(&[0.,0.,0.,1.,2.,3.,4.,1.,1.,1.]));
    world.insert_resource(transforms);
    let mut terrain=TerrainHeightsData::<TerrainHeightSsbo>::new();terrain.set_height_range(3.,3.);world.insert_resource(terrain);
    let mut camera=MainCamera::new(1.);camera.write_matrix(0,&Mat4::from_diagonal(glam::Vec4::new(1.,2.,1.,1.)));world.insert_resource(camera);
    world.insert_resource(WindowSize::new(1,1));
    world.insert_resource(MouseDepthValue{view_depth:1.,..Default::default()});
    world.insert_resource(GameTime{delta:0.1,..Default::default()});
    let cursor=if case.small {Vec3::ZERO} else {Vec3::new(4.,0.,5.)};
    world.insert_resource(CameraCursorRay{origin:cursor,dir:Vec3::NEG_Y});
    let widget=WidgetId(0x1122334455667788);
    let mut ui=UiState::new(UiInteraction{native_tag:2,native_phase:case.raw,widget});ui.set_intersection_tag(0);ui.set_intersection_point(Vec3::new(4.,7.,5.));world.insert_resource(ui);
    world.init_resource::<DecoratorAffordanceDispatcher>();
    world.init_resource::<Events<country_core::systems::ui_clutter::ui_focus_decoclutter::RequestMoveClutter>>();
    world.init_resource::<Events<RequestRotateDecorator>>();
    let request=country_core::systems::ui_clutter::ui_focus_decoclutter::request_focused_decorator_rotation(world.resource::<UiState>(),widget,id,world.resource::<DecoratorStorage>(),0.,0.75).unwrap();
    world.resource_mut::<Events<RequestRotateDecorator>>().send(request);
    world.insert_resource(country_core::systems::mode_manager::AppMode::Editing(country_core::systems::mode_manager::EditSubject::DecoClutter{decorator_id:id.0}));
    world.init_resource::<country_core::resources::gui::EscMenuState>();
    world.init_resource::<country_core::resources::cursor_terrain_raycast::CursorTerrainRaycast>();
    world.insert_resource(country_core::systems::collision::world::RaycastWorld::new());
    world.init_resource::<UiSignifierStream>();world.init_resource::<Events<PlayDecoratorSoundCmd>>();
    world.init_resource::<DeferredDecoratorOpEvents>();world.init_resource::<Events<DecoratorOpEvent>>();world.init_resource::<DecoratorArchivist<()>>();
    world.init_resource::<DeferredDecoratorEditHistory>();world.init_resource::<DecoratorBackup>();
    let mut schedule=Schedule::default();schedule.add_systems((super::ui_decorator_affordance_dispatch::ui_dispatch_focused_decorator_requests,ui_rotate_decorator::<()>,unleash_decorator_op_events).chain());schedule.run(&mut world);
    let after=*world.resource::<DecoratorStorage>().get(addr).unwrap().get(id).unwrap();
    let op=bytes(case.op);
    if op.is_empty(){assert_eq!(after,before);} else {
        let mut expected=input;
        let in_place=u64::from_le_bytes(op[16..24].try_into().unwrap())==3;
        if in_place {expected[0x2c..0x30].copy_from_slice(&before.decorator_id.wrapping_add(1).to_le_bytes());expected[0x45]=5;}
        else {let at=if case.dst==4 {16} else {8};expected[at..at+4].copy_from_slice(&op[32+at..36+at]);}
        let actual=crate::apply_decorator_op::info_to_bytes(after);
        let yaw_at=if case.dst==4 {16} else {8};
        for at in 0..72 {if !in_place && (yaw_at..yaw_at+4).contains(&at){continue;}assert_eq!(actual[at],expected[at],"dst{} raw{} ty{} small{} byte{at:x}",case.dst,case.raw,case.ty,case.small);}
        if !in_place {close(scalar(&actual,yaw_at),scalar(&expected,yaw_at));}
        assert_eq!(world.resource::<DeferredDecoratorEditHistory>().records.len(),1);
        let archived=world.resource::<DecoratorArchivist<()>>();
        let tracked=if case.dst==4 {archived.special2.as_ref()} else {archived.special1.as_ref()}.unwrap();
        assert_eq!(tracked.items[&id.0].0,input,"archive must retain original complete72B Info");
        let queue=world.resource::<Events<DecoratorOpEvent>>();let events:Vec<[u8;0x88]>=queue.get_cursor().read(queue).map(|event|event.0).collect();assert_eq!(events.len(),1);
        assert_eq!(word(&events[0],0x68),id.0);
        assert_eq!(events[0][0x80],u8::from(case.raw>1));assert_eq!(events[0][0x81],case.ty);
        assert_eq!(world.resource::<DecoratorStorage>().lookup_storage(id),Some(addr));
        let native_event=bytes(case.event);
        let actual_event=&events[0];
        for at in (0..24).chain(0x50..0x66).chain(0x68..0x6c).chain(0x70..0x7c).chain(0x80..0x82) {
            assert_eq!(actual_event[at],native_event[at],"native event byte{at:x} dst{} raw{} ty{} small{}",case.dst,case.raw,case.ty,case.small);
        }
        if !in_place {
            for at in 0x18..0x28 {assert_eq!(actual_event[at],native_event[at]);}
            let yaw_at=if case.dst==4 {0x30} else {0x28};
            close(scalar(actual_event,yaw_at),scalar(&native_event,yaw_at));
            if case.dst==4 {for at in 0x28..0x30 {assert_eq!(actual_event[at],native_event[at]);}}
            assert_eq!(actual_event[0x42],native_event[0x42]);
            assert_eq!(actual_event[0x48],native_event[0x48]);
        }

    }
    assert_eq!(world.resource::<DeferredDecoratorEditHistory>().pending,case.raw<2);
    assert_eq!(world.resource::<DecoratorBackup>().reset_after,case.raw<2);
    let expected_audio=bytes(case.audio);
    let events:Vec<_>=world.resource::<Events<PlayDecoratorSoundCmd>>().get_cursor().read(world.resource::<Events<PlayDecoratorSoundCmd>>()).copied().collect();
    if expected_audio.is_empty(){assert!(events.is_empty());}else{assert_eq!(events.len(),1);let event=events[0];assert_eq!(event.kind,expected_audio[8]);close(event.ratio,scalar(&expected_audio,12));assert_eq!(event.position_context,u64::from_le_bytes(expected_audio[16..24].try_into().unwrap()));assert_eq!(event.position,Vec3::new(scalar(&expected_audio,24),scalar(&expected_audio,28),scalar(&expected_audio,32)));assert!(!event.flag);}
 }
}
